/* Service schedules are vehicle-specific. WhatsApp reminders require user review and sending. */
groups.find(g=>g[0]==='OPERATIONS')[1].push(['service-reminders','Service Reminders','bell']);titles['service-reminders']='Service Reminders';
schemas.bikes.push(section('SERVICE DUE DATE & REMINDERS'),{key:'lastServiceDate',label:'Last Service Date',type:'date'},{key:'nextServiceDate',label:'Next Service Due Date',type:'date'},{key:'nextServiceType',label:'Next Service / Work Required'},{key:'serviceReminderNotes',label:'Service Reminder Notes',type:'textarea',full:true});
function serviceDueDays(b,date=today()){if(!validAmcDate(b.nextServiceDate))return null;return Math.round((Date.parse(b.nextServiceDate+'T00:00:00Z')-Date.parse(date+'T00:00:00Z'))/86400000)}
function serviceDueStatus(b,date=today()){let days=serviceDueDays(b,date);return days===null?'Not Scheduled':days<0?'Overdue':days===0?'Due Today':'Upcoming'}
function validateVehicleService(b){if(b.lastServiceDate&&!validAmcDate(b.lastServiceDate))throw Error('Enter a valid last service date.');if(b.nextServiceDate&&!validAmcDate(b.nextServiceDate))throw Error('Enter a valid next service due date.');if(b.lastServiceDate&&b.nextServiceDate&&b.nextServiceDate<b.lastServiceDate)throw Error('Next service due date must be on or after the last service date.');return true}
function vehicleServiceMessage(b){let c=find('customers',b.customer),days=serviceDueDays(b),garage=db.settings.name||'Our Garage',phone=db.settings.phone||'';return `Hello ${c?.name||'Customer'} 👋\n\nIt’s time for the next service of your vehicle ${b.number}${[b.brand,b.model].filter(Boolean).length?' ('+[b.brand,b.model].filter(Boolean).join(' ')+')':''}.\n${days<0?'The service was due on':'The service is due on'} ${b.nextServiceDate}.\n${b.nextServiceType?'Service: '+b.nextServiceType+'\n':''}\nRegular servicing helps maintain better performance, safety, and mileage.\nBook your service with ${garage} today.\n\n${phone?'📞 '+phone+'\n':''}Thank you for trusting us. 🛠️🏍️`}
function serviceReminderLastLog(b){return (db.serviceReminderLogs||[]).filter(l=>l.vehicle===b.id&&l.dueDate===b.nextServiceDate).sort((a,b)=>b.at.localeCompare(a.at))[0]}
async function saveServiceSchedule(id,data){
 validateVehicleService(data);
 const fields=['lastServiceDate','nextServiceDate','nextServiceType','serviceReminderNotes'];
 const schedule=Object.fromEntries(fields.map(key=>[key,data[key]||'']));
 const response=await fetch('/api/vehicles',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({id,...schedule})});
 const result=await response.json();
 if(!response.ok||result.data?.id!==id)throw Error(result.error||'Service schedule could not be saved.');
 db.bikes=db.bikes.map(vehicle=>vehicle.id===id?result.data:vehicle);
 save();
 toast('Service schedule saved to Cloudflare D1.');
 return true;
}
function openServiceSchedule(id){let b=id?find('bikes',id):null;openModal('Schedule Vehicle Service Reminder',`<form id="serviceScheduleForm"><div class="formbody"><div class="formgrid">${field({key:'vehicle',label:'Vehicle',type:'select',options:()=>db.bikes.map(v=>({value:v.id,label:v.number+' — '+name('customers',v.customer)})),required:true},{vehicle:b?.id||''})}${field({key:'lastServiceDate',label:'Last Service Date',type:'date'},b||{})}${field({key:'nextServiceDate',label:'Next Service Due Date',type:'date',required:true},b||{})}${field({key:'nextServiceType',label:'Next Service / Work Required'},b||{})}${field({key:'serviceReminderNotes',label:'Internal Notes',type:'textarea',full:true},b||{})}</div></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button type="submit" class="btn">Save Reminder Schedule</button></div></form>`);let form=$('#serviceScheduleForm');form.querySelector('[name="vehicle"]').onchange=e=>{let record=find('bikes',e.target.value);if(record)for(let key of ['lastServiceDate','nextServiceDate','nextServiceType','serviceReminderNotes'])form.querySelector('[name="'+key+'"]').value=record[key]||''};form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');if(button.disabled)return;const values=Object.fromEntries(new FormData(form));button.disabled=true;try{await saveServiceSchedule(values.vehicle,values);if(form.isConnected)closeModal();render()}catch(err){toast(err.message)}finally{button.disabled=false}}}
function logServiceReminder(id,note){let b=find('bikes',id);if(!b||serviceDueDays(b)===null)throw Error('Set a service due date first.');let before=structuredClone(db);db.serviceReminderLogs=db.serviceReminderLogs||[];db.serviceReminderLogs.push({id:'SR-'+Date.now()+'-'+Math.random().toString(36).slice(2,6),vehicle:id,dueDate:b.nextServiceDate,at:new Date().toISOString(),note:String(note||'').slice(0,500),status:'User confirmed sent'});audit('Service Reminder',b.number+' marked sent by user for '+b.nextServiceDate);if(save('Reminder recorded as sent by you')===false){db=before;return false}return true}
let serviceReminderFilter='due',serviceReminderWindow='30';
function serviceReminderRows(){return db.bikes.filter(b=>matches({...b,customer:name('customers',b.customer),mobile:find('customers',b.customer)?.mobile})).filter(b=>{let days=serviceDueDays(b);return serviceReminderFilter==='all'||serviceReminderFilter==='due'&&days!==null&&days<=0||serviceReminderFilter==='overdue'&&days!==null&&days<0||serviceReminderFilter==='today'&&days===0||serviceReminderFilter==='upcoming'&&days!==null&&days>0&&days<=Number(serviceReminderWindow)||serviceReminderFilter==='unscheduled'&&days===null}).sort((a,b)=>(a.nextServiceDate||'9999').localeCompare(b.nextServiceDate||'9999'))}
function serviceRemindersPage(){let all=db.bikes;return summary([['OVERDUE',all.filter(b=>serviceDueStatus(b)==='Overdue').length],['DUE TODAY',all.filter(b=>serviceDueStatus(b)==='Due Today').length],['DUE WITHIN 30 DAYS',all.filter(b=>{let days=serviceDueDays(b);return days!==null&&days>0&&days<=30}).length],['NOT SCHEDULED',all.filter(b=>serviceDueDays(b)===null).length]])+`<div class="notice">Due dates are set per vehicle. WhatsApp opens a message for review; nothing is sent automatically. Updating a due date starts a new reminder cycle.</div>`+toolbar('',`<select id="serviceReminderFilter" aria-label="Service reminder status">${opts([{value:'due',label:'Due Today & Overdue'},{value:'overdue',label:'Overdue'},{value:'today',label:'Due Today'},{value:'upcoming',label:'Upcoming'},{value:'unscheduled',label:'Not Scheduled'},{value:'all',label:'All Vehicles'}],serviceReminderFilter)}</select><select id="serviceReminderWindow" aria-label="Upcoming service window">${opts([{value:'7',label:'Next 7 Days'},{value:'30',label:'Next 30 Days'},{value:'90',label:'Next 90 Days'}],serviceReminderWindow)}</select><button type="button" class="btn" id="scheduleVehicleService">Schedule Service</button>`)+table(['Vehicle Number','Make / Model','Customer','Mobile','Last Service','Next Service Due','Service Required','Status','Days Due / Remaining','Last Reminder Sent','Notes','Actions'],serviceReminderRows().map(b=>{let c=find('customers',b.customer),days=serviceDueDays(b),log=serviceReminderLastLog(b);return [esc(b.number),esc([b.brand,b.model].filter(Boolean).join(' ')),esc(c?.name||'—'),esc(c?.mobile||'—'),esc(b.lastServiceDate||'—'),esc(b.nextServiceDate||'—'),esc(b.nextServiceType||'—'),badge(serviceDueStatus(b)),days===null?'—':days<0?Math.abs(days)+' days overdue':days===0?'Due today':days+' days remaining',log?esc(uiDateTime(log.at))+' (manual)':'—',esc(b.serviceReminderNotes||'—'),`<div class="rowactions"><button class="btn small extraAction green" type="button" data-service-whatsapp="${esc(b.id)}" title="WhatsApp Service Reminder" ${days===null?'disabled':''}>${whatsappIcon()}</button><button class="btn small editButton" type="button" data-service-schedule="${esc(b.id)}" title="Edit Service Due Date">${icon('calendar')}</button></div>`]}))}
const basicBeforeServiceReminders=basicPage;
basicPage=function(key){return key==='service-reminders'?serviceRemindersPage():basicBeforeServiceReminders(key)};
const editBeforeVehicleService=editRecord;
editRecord=function(key,id,initial){editBeforeVehicleService(key,id,initial);if(key!=='bikes')return;let form=$('#recordForm');if(!form)return;let submit=form.onsubmit;form.onsubmit=e=>{try{validateVehicleService(Object.fromEntries(new FormData(form)))}catch(err){e.preventDefault();return toast(err.message)}return submit(e)}};
const renderBeforeServiceReminders=render;
render=function(){renderBeforeServiceReminders();if(page==='service-reminders'){for(let button of $$('[data-service-whatsapp]')){let sent=document.createElement('button');sent.type='button';sent.className='btn small extraAction blue';sent.dataset.serviceSent=button.dataset.serviceWhatsapp;sent.textContent='Mark Sent';sent.title='Record service reminder sent';button.closest('.rowactions')?.append(sent)}for(let [id,set]of [['serviceReminderFilter',v=>serviceReminderFilter=v],['serviceReminderWindow',v=>serviceReminderWindow=v]])if($('#'+id))$('#'+id).onchange=e=>{set(e.target.value);render()};if($('#scheduleVehicleService'))$('#scheduleVehicleService').onclick=()=>openServiceSchedule();for(let button of $$('[data-service-schedule]'))button.onclick=()=>openServiceSchedule(button.dataset.serviceSchedule);for(let button of $$('[data-service-whatsapp]'))button.onclick=()=>{let b=find('bikes',button.dataset.serviceWhatsapp),c=find('customers',b.customer);messagePreview(c?.mobile,vehicleServiceMessage(b))};for(let button of $$('[data-service-sent]'))button.onclick=()=>{let id=button.dataset.serviceSent,b=find('bikes',id);openModal('Record Service Reminder Sent',`<form id="serviceSentForm"><div class="formbody"><p>Confirm that you have sent the reminder for <strong>${esc(b.number)}</strong>, due ${esc(b.nextServiceDate)}. Opening WhatsApp alone does not confirm sending.</p><label class="field"><span>Note / Contact Method</span><input name="note" maxlength="500" placeholder="For example: WhatsApp reminder sent"></label></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button type="submit" class="btn">Confirm I Sent the Reminder</button></div></form>`);$('#serviceSentForm').onsubmit=e=>{e.preventDefault();try{if(logServiceReminder(id,new FormData(e.target).get('note'))){closeModal();render()}}catch(err){toast(err.message)}}}}if(page==='bikes')for(let button of $$('#content [data-edit^="bikes|"]')){let id=button.dataset.edit.split('|')[1],b=find('bikes',id),details=button.closest('.bikecard')?.querySelector('.bikedetail');if(details)details.insertAdjacentHTML('beforeend',`<p><strong>Next Service:</strong> ${esc(b.nextServiceDate||'Not scheduled')} · ${esc(serviceDueStatus(b))}</p>`)}};
if(location.hash==='#service-reminders')page='service-reminders';render();
